PRAGMA foreign_keys = ON;
ALTER TABLE products ADD COLUMN short_name TEXT NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN landing_collection TEXT NOT NULL DEFAULT 'story' CHECK(landing_collection IN ('story','emotion','dedicated'));
ALTER TABLE products ADD COLUMN landing_order INTEGER NOT NULL DEFAULT 0;
ALTER TABLE products ADD COLUMN storefront_state TEXT NOT NULL DEFAULT 'coming_soon' CHECK(storefront_state IN ('available','coming_soon','out_of_stock'));
ALTER TABLE products ADD COLUMN is_featured INTEGER NOT NULL DEFAULT 0 CHECK(is_featured IN (0,1));
ALTER TABLE products ADD COLUMN preorder_enabled INTEGER NOT NULL DEFAULT 0 CHECK(preorder_enabled IN (0,1));
ALTER TABLE products ADD COLUMN release_note TEXT NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN details_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(details_json));
CREATE TABLE product_interest (
 id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id), email TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('notify','preorder')), status TEXT NOT NULL DEFAULT 'new' CHECK(status IN ('new','contacted','closed')),
 created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 UNIQUE(product_id,email,kind)
);
CREATE INDEX product_interest_status_idx ON product_interest(status,created_at);

