UPDATE products SET short_name='Harry Potter', landing_collection='story', landing_order=0, storefront_state='available', is_featured=1, details_json='["Dimensiuni aprox.: 6,5 × 5 × 4 cm","Înălțime cu capacul deschis: aprox. 6,2 cm","Funcționare: mecanică, prin rotirea manuală a manivelei","Obiect decorativ / de colecție 14+; nu este jucărie"]',
name=CASE WHEN version=1 THEN 'Cutiuță Muzicală Harry Potter cu Manivelă – Cadou de Colecție 14+' ELSE name END, tagline=CASE WHEN version=1 THEN 'Un mic obiect de colecție pentru cei care vor să păstreze puțină magie aproape.' ELSE tagline END, description=CASE WHEN version=1 THEN 'Cutiuța muzicală inspirată din universul Harry Potter combină lemnul închis la culoare, detaliile tematice și mecanismul metalic vizibil într-un obiect compact și memorabil. Ridici capacul, descoperi grafica interioară, apoi rotești ușor manivela pentru a pune mecanismul muzical în mișcare — fără baterii și fără încărcare. Redă o parte din piesa legendară a seriei de filme, creând o atmosferă magică și fidelă, care trezește emoții unice fanilor și colecționarilor.' ELSE description END, story=CASE WHEN version=1 THEN 'Este potrivită pentru fani, colecționari, adolescenți 14+, cadouri de aniversare, Crăciun, Secret Santa, dar și ca decor pentru birou, bibliotecă, raft sau vitrină. Mică la dimensiuni. Mare la capitolul magie. Imaginile sunt orientative și pot include elemente decorative care nu fac parte din produs.' ELSE story END WHERE slug='hp-keeper';
