UPDATE products SET short_name='You Are My Sunshine', landing_collection='emotion', landing_order=4, storefront_state='available', is_featured=0, details_json='["Melodie: You Are My Sunshine","Dimensiuni: aprox. 6,5 × 3,8 × 5 cm / 2.55 × 1.5 × 1.97 in","Lemn închis la culoare, ornamente decorative și mecanism metalic vizibil","Obiect de colecție 14+; nu este jucărie"]',
name=CASE WHEN version=1 THEN 'Cutiuță Muzicală „You Are My Sunshine” cu Manivelă – Cadou de Colecție 14+' ELSE name END, tagline=CASE WHEN version=1 THEN 'Uneori, cele mai frumoase amintiri încap într-o cutiuță.' ELSE tagline END, description=CASE WHEN version=1 THEN 'Cutiuța muzicală „You Are My Sunshine” este un mic obiect de colecție creat pentru a transforma un gest simplu într-un moment special. Designul din lemn, detaliile decorative și mesajul ascuns sub capac o fac potrivită atât pentru cupluri și familie, cât și pentru cei care iubesc obiectele cu poveste. Rotești ușor manivela metalică, cilindrul mecanismului pune în mișcare pieptenele muzical, iar melodia începe să se audă — fără baterii și fără încărcare.' ELSE description END, story=CASE WHEN version=1 THEN 'Mecanismul rămâne vizibil atunci când capacul este deschis, ceea ce îi oferă un farmec aparte și o transformă într-un obiect interesant de păstrat și expus. Este o alegere potrivită pentru aniversări, zile de naștere, Valentine’s Day, Crăciun, cadouri pentru partener, părinți sau persoane apropiate, dar și ca decor pentru birou, bibliotecă, vitrină, dormitor sau o colecție personală. Mică la dimensiuni, dar făcută să păstreze momente mari. Imaginile de prezentare sunt orientative; decorurile și accesoriile din fotografii nu sunt incluse.' ELSE story END WHERE slug='sunshine';
